mapper.select:
        select mn.*,pre.p_name as pName,sys.c_name as cName
        from Final_Accounting_Report mn
        left join pre_project pre on mn.p_id = pre.p_id
        left join sys_company sys on pre.P_Construction_Unit =sys.c_id
        
            mn.status=1
            
                and sys.c_name in
                
                    #{cName}
                
            
            
                and pre.p_name in
                
                    #{pName}
                
            
            
                and mn.state in
                
                    #{state}
                
            
            
                and mn.approved_Budget_Amount in
                
                    #{approvedBudgetAmount}
                
            
            
                and mn.audit_Contract_Money in
                
                    #{auditContractMoney}
                
            
            
                and mn.create_Uname in
                
                    #{createUname}
                
            

        
        order by mn.Create_Time desc
